namespace MymoneyMcp.Domain.Accounts;

/// <summary>
/// A financial account owned by one account group: the root of all financial data
/// (Constitution II). Data rules: specs/001-system-foundation/data-model.md.
/// </summary>
public sealed class Account
{
    private Account()
    {
    }

    /// <summary>Generated by the app.</summary>
    public Guid Id { get; private set; }

    /// <summary>Required, trimmed, not blank.</summary>
    public string DisplayName { get; private set; } = string.Empty;

    /// <summary>Required, trimmed, not blank. Exact, case-sensitive match.</summary>
    public string Group { get; private set; } = string.Empty;

    /// <summary>Set on insert (UTC).</summary>
    public DateTimeOffset CreatedAt { get; private set; }

    public static Account Create(string displayName, string group, DateTimeOffset createdAt) =>
        new()
        {
            Id = Guid.CreateVersion7(),
            DisplayName = RequireText(displayName, nameof(displayName)),
            Group = RequireText(group, nameof(group)),
            CreatedAt = createdAt.ToUniversalTime(),
        };

    private static string RequireText(string value, string paramName)
    {
        var trimmed = value?.Trim();
        return string.IsNullOrEmpty(trimmed)
            ? throw new ArgumentException("Value must not be blank.", paramName)
            : trimmed;
    }
}
